//! 🧪️ Actual native root callbacks preserve one source through semantic failure and paid closure.
#[path="../🦀️.rs"]
mod native_caller;
use native_caller::{NativeFrameCaller,NativeFrameEventIssuer,NativeFrameRootPolicyV1};
use semio_framework_job::{Generation,OperationId,OriginalCallerSourceLoan,OriginalTurnFailure,OriginalTurnPrimary};
use semio_framework_plugin_guest_contract::original_actor_context::OriginalActorEntryFailure;
use semio_framework_value::{RetainedCloneStep,ValueError,ValueRefusalKind};
#[global_allocator]
static HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
fn clock()->Option<u64>{Some(1000)}
fn observe<T>(run:impl FnOnce()->T)->(T,usize,usize){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(run);(value,heap.requested_bytes,heap.released_bytes)}
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap()}

#[test]
fn native_original_root_callbacks_keep_source_epoch_failure_and_paid_terminal_closure(){
 let fixture=fixture();let policy:NativeFrameRootPolicyV1=serde_json::from_value(fixture["policy"].clone()).unwrap();let(operation,generation)=(OperationId(fixture["operation"].as_u64().unwrap()),Generation(fixture["generation"].as_u64().unwrap()));
 let(mut caller,born,freed)=observe(||NativeFrameCaller::new(operation,generation,clock,policy).unwrap());assert_eq!((born,freed),(0,0));let(mut born,mut freed)=(born,freed);let mut phases=0;
 while !caller.ready(){let unspent=caller.retained_remaining();let work=caller.fuel_remaining();let(call,birth,release)=observe(||caller.admit_step().unwrap());assert_eq!(call.input.grant,unspent);assert_eq!(call.input.work.fuel,work);assert_eq!((birth,release),(call.receipt_spent.retained_capacity_bytes,call.receipt_spent.released_bytes));call.receipt().unwrap().validate_for(call.input).unwrap();assert_eq!(call.input.epoch,phases+1);assert_eq!(call.work_units_spent,1);assert!(call.result.is_ok());born+=birth;freed+=release;phases+=1;assert!(phases<=5)}assert_eq!(phases,fixture["rootAdmissionPhases"].as_array().unwrap().len()as u64);
 let mut source:Option<OriginalCallerSourceLoan>=None;let mut recipient=None;let mut cancellation=None;let mut actual_epoch=0;
 for presentation in fixture["presentationGenerations"].as_array().unwrap(){let(call,birth,release)=observe(||caller.dispatch_step(|cx|{
  assert_eq!(cx.operation(),operation);assert_eq!(cx.generation(),generation);assert_ne!(cx.generation().0,presentation.as_u64().unwrap());assert_eq!(cx.deadline_us(),fixture["deadline"].as_u64().unwrap());assert!(std::ptr::fn_addr_eq(cx.clock_source(),clock as fn()->Option<u64>));let stamp=cx.original_source_epoch().unwrap();assert!(cx.bind_original_source_epoch(stamp+1).is_err());assert_eq!(cx.original_source_epoch(),Some(stamp));actual_epoch=stamp;
  let identity=cx.original_recipient_identity();assert_eq!(*recipient.get_or_insert(identity),identity);let identity=cx.borrowed_original_cancel_token()?as*const _ as usize;assert_eq!(*cancellation.get_or_insert(identity),identity);
  if let Some(source)=source.as_ref(){source.validate_context(cx)?}else{source=cx.original_source_parent()?.admit_loan(cx)?;assert!(source.is_some())}Ok(())
 }).unwrap());assert!(call.result.is_ok());assert_eq!(actual_epoch,call.input.epoch);assert_eq!((birth,release),(call.receipt_spent.retained_capacity_bytes,call.receipt_spent.released_bytes));born+=birth;freed+=release;}
 let(message_pointer,call,birth,release)={let message="original native root child refusal";let(call,birth,release)=observe(||caller.dispatch_step::<()>(|cx|{let progress=cx.borrowed_original_cancel_token()?.signal_cancelled_flag_step(cx.retained_grant()).unwrap();cx.consume_retained(progress)?;cx.consume_fuel(1);Err(OriginalTurnFailure{primary:OriginalTurnPrimary::Value(ValueError::literal(ValueRefusalKind::OwnershipLimit,message)),receipt_refusal:Some(ValueError::literal(ValueRefusalKind::WorkLimit,"original native child receipt refusal")),context_refusal:Some(ValueError::literal(ValueRefusalKind::DepthLimit,"original native child context refusal"))})}).unwrap());(message.as_ptr(),call,birth,release)};assert!(matches!(call.result,Err(OriginalActorEntryFailure::Semantic)));assert_eq!(caller.original_failure().unwrap().primary_value().unwrap().message.as_ptr(),message_pointer);assert_eq!(caller.original_failure().unwrap().primary_value().unwrap().message,fixture["fault"]["message"].as_str().unwrap());assert_eq!(caller.original_failure().unwrap().primary_value().unwrap().kind.as_str(),fixture["fault"]["kind"].as_str().unwrap());for(actual,field)in[(caller.original_failure().unwrap().receipt_refusal.as_ref().unwrap(),"receiptRefusal"),(caller.original_failure().unwrap().context_refusal.as_ref().unwrap(),"contextRefusal")]{assert_eq!(actual.kind.as_str(),fixture["fault"][field]["kind"].as_str().unwrap());assert_eq!(actual.message,fixture["fault"][field]["message"].as_str().unwrap());}assert_eq!((birth,release),(call.receipt_spent.retained_capacity_bytes,call.receipt_spent.released_bytes));born+=birth;freed+=release;
 let(call,birth,release)=observe(||caller.dispatch_cleanup_step(|cx|{assert!(cx.is_cancelled());let before=cx.retained_progress();let loan=semio_framework_value::RetainedCloneGrant{maximum_items:0,..cx.retained_grant()};cx.with_retained_loan(loan,|cx|{let original=cx.original_source_parent()?;let step=source.as_mut().unwrap().close_step(original,cx)?;assert_eq!(step.progress(),Default::default());Ok(())})?;assert_eq!(cx.retained_progress(),before);Ok(())}).unwrap());assert!(call.result.is_ok());assert_eq!((birth,release),(0,0));assert!(!source.as_ref().unwrap().terminal_is_empty());assert_eq!(caller.original_failure().unwrap().primary_value().unwrap().message.as_ptr(),message_pointer);
 let(call,birth,release)=observe(||caller.dispatch_cleanup_step(|cx|{assert!(cx.is_cancelled());source.as_mut().unwrap().close_step(cx.original_source_parent()?,cx)?;Ok(())}).unwrap());assert!(call.result.is_ok());assert!(source.as_ref().unwrap().terminal_is_empty());assert!(source.as_ref().unwrap().original_clock_source().is_err());assert_eq!((birth,release),(call.receipt_spent.retained_capacity_bytes,call.receipt_spent.released_bytes));born+=birth;freed+=release;let(_,birth,release)=observe(||drop(source.take()));assert_eq!((birth,release),(0,0));
 for _ in 0..256{if caller.terminal_is_empty(){break}let(call,birth,release)=observe(||caller.close_step().unwrap());assert!(call.result.is_ok());call.receipt().unwrap().validate_for(call.input).unwrap();assert_eq!((birth,release),(call.receipt_spent.retained_capacity_bytes,call.receipt_spent.released_bytes));born+=birth;freed+=release;}assert!(caller.terminal_is_empty());assert!(!caller.ready());assert_eq!(born,freed);let(_,birth,release)=observe(||drop(caller));assert_eq!((birth,release),(0,0));
 let mut denied=NativeFrameCaller::new(operation,generation,clock,NativeFrameRootPolicyV1{fuel:0,retirement_reserve:native_caller::NativeFrameRetirementReserveV1{fuel:0,..policy.retirement_reserve},..policy}).unwrap();let(call,birth,release)=observe(||denied.admit_step().unwrap());assert!(!call.result.unwrap().ready);assert_eq!((birth,release),(0,0));let(call,birth,release)=observe(||denied.dispatch_cleanup_step::<()>(|_|panic!("denied original body called")).unwrap());assert!(matches!(call.result,Err(OriginalActorEntryFailure::Authority(_))));assert_eq!((birth,release),(0,0));assert!(matches!(denied.close_step().unwrap().result,Ok(RetainedCloneStep::Complete(_))));drop(denied);
 assert!(NativeFrameCaller::new(operation,generation,||None,policy).is_err());
}

static EVENT_CLOCK:std::sync::atomic::AtomicU64=std::sync::atomic::AtomicU64::new(0);
static EVENT_CLOCK_TEST:std::sync::Mutex<()>=std::sync::Mutex::new(());
fn event_clock()->Option<u64>{Some(EVENT_CLOCK.load(std::sync::atomic::Ordering::SeqCst))}
#[test]
fn native_production_policy_same_expired_source_denies_semantics_and_pays_original_partial_close(){
 let _serial=EVENT_CLOCK_TEST.lock().unwrap();let law=fixture();let expected:NativeFrameRootPolicyV1=serde_json::from_value(law["productionPolicy"].clone()).unwrap();let policy=NativeFrameRootPolicyV1::initiating_event();assert_eq!(policy,expected);EVENT_CLOCK.store(1000000,std::sync::atomic::Ordering::SeqCst);
 let(mut caller,birth,release)=observe(||NativeFrameCaller::new(OperationId(71014),Generation(9),event_clock,policy).unwrap());assert_eq!((birth,release),(0,0));let(mut born,mut freed)=(0,0);for _ in 0..8{if caller.ready(){break}let(call,birth,release)=observe(||caller.admit_step().unwrap());assert!(call.result.is_ok());assert_eq!((birth,release),(call.receipt_spent.retained_capacity_bytes,call.receipt_spent.released_bytes));born+=birth;freed+=release;}assert!(caller.ready());let binding=caller.original_clock_binding();assert_ne!(binding,0);assert!(caller.observe_original_clock(binding).is_some());assert!(caller.observe_original_clock(binding.wrapping_add(1)).is_none());
 let(mut source,mut bytes,mut recipient)=(None,None,None);let unspent=caller.retained_remaining();let total_fuel=caller.fuel_remaining();let(call,birth,release)=observe(||caller.dispatch_step(|cx|{assert_eq!(cx.original_total_retained_grant(),unspent);assert_eq!(cx.original_total_fuel_remaining(),total_fuel);recipient=Some(cx.original_recipient_identity());assert_eq!(cx.original_clock_binding(),Some(binding));assert!(cx.bind_original_clock_binding(binding.wrapping_add(1)).is_err());assert_eq!(cx.original_clock_binding(),Some(binding));assert_eq!(cx.original_absolute_deadline_us(),cx.deadline_us());assert_eq!(cx.original_total_fuel_remaining()-cx.fuel_remaining(),policy.retirement_reserve.fuel);assert!(cx.original_total_retained_grant().maximum_items>cx.retained_grant().maximum_items);source=cx.original_source_parent()?.admit_loan(cx)?;assert!(source.is_some());let(clock_binding,source_clock,source_deadline)=source.as_ref().unwrap().original_clock_source()?;assert_eq!(clock_binding,binding);assert!(std::ptr::fn_addr_eq(source_clock,cx.clock_source()));assert_eq!(source_deadline,cx.original_absolute_deadline_us());let mut body=Vec::<u8>::new();body.try_reserve_exact(17).unwrap();let capacity=body.capacity();bytes=Some(body);cx.consume_retained(semio_framework_value::RetainedCloneProgress{copied_items:1,retained_capacity_bytes:capacity,..Default::default()})?;cx.consume_fuel(1);Ok(())}).unwrap());assert!(call.result.is_ok());assert_eq!((birth,release),(call.receipt_spent.retained_capacity_bytes,call.receipt_spent.released_bytes));born+=birth;freed+=release;let deadline=caller.deadline_us();let stock=caller.retained_spent();let fuel=caller.fuel_remaining();EVENT_CLOCK.store(deadline+1,std::sync::atomic::Ordering::SeqCst);
 let(call,birth,release)=observe(||caller.dispatch_step::<()>(|_|panic!("expired original source executed semantic producer")).unwrap());assert!(matches!(call.result,Err(OriginalActorEntryFailure::Authority(_))));assert_eq!((birth,release),(0,0));assert_eq!(caller.retained_spent(),stock);assert_eq!(caller.fuel_remaining(),fuel);
 let unspent=caller.retained_remaining();let total_fuel=caller.fuel_remaining();let(call,birth,release)=observe(||caller.dispatch_cleanup_step(|cx|{assert_eq!(cx.original_total_retained_grant(),unspent);assert_eq!(cx.original_total_fuel_remaining(),total_fuel);assert!(cx.should_yield());assert!(cx.deadline_exceeded());assert!(!cx.retirement_should_yield());assert_eq!(cx.deadline_us(),deadline);assert_eq!(cx.original_recipient_identity(),recipient.unwrap());assert!(std::ptr::fn_addr_eq(cx.clock_source(),event_clock as fn()->Option<u64>));assert!(cx.original_source_parent()?.admit_loan(cx)?.is_none());let capacity=bytes.as_ref().unwrap().capacity();let denial=semio_framework_value::RetainedCloneGrant{maximum_release_bytes:capacity-1,..cx.retained_grant()};cx.with_retained_loan(denial,|same|semio_framework_job::close_original_retained_step(same,semio_framework_value::RetirementDemand{release_bytes:capacity,depth:1,..Default::default()},|_|panic!("denied original body released")))?;assert!(bytes.is_some());Ok(())}).unwrap());assert!(call.result.is_ok());assert_eq!((birth,release),(0,0));
 let(call,birth,release)=observe(||caller.dispatch_cleanup_step(|cx|{let capacity=bytes.as_ref().unwrap().capacity();semio_framework_job::close_original_retained_step(cx,semio_framework_value::RetirementDemand{release_bytes:capacity,depth:1,..Default::default()},|_|{drop(bytes.take());Ok(RetainedCloneStep::Complete(semio_framework_value::RetainedCloneProgress{copied_items:1,released_bytes:capacity,..Default::default()}))})?;source.as_mut().unwrap().close_step(cx.original_source_parent()?,cx)?;Ok(())}).unwrap());assert!(call.result.is_ok());assert!(bytes.is_none());assert!(source.as_ref().unwrap().terminal_is_empty());assert_eq!((birth,release),(call.receipt_spent.retained_capacity_bytes,call.receipt_spent.released_bytes));born+=birth;freed+=release;drop(source.take());assert_eq!(caller.deadline_us(),deadline);
 for _ in 0..256{if caller.terminal_is_empty(){break}let(call,birth,release)=observe(||caller.close_step().unwrap());assert!(call.result.is_ok());assert_eq!((birth,release),(call.receipt_spent.retained_capacity_bytes,call.receipt_spent.released_bytes));born+=birth;freed+=release;}assert!(caller.terminal_is_empty());assert_eq!(born,freed);let(_,birth,release)=observe(||drop(caller));assert_eq!((birth,release),(0,0));
}
#[test]
fn native_initiating_event_same_source_borrow_denial_return_and_distinct_next_operation(){
 let _serial=EVENT_CLOCK_TEST.lock().unwrap();
 let fixture=fixture();let law=&fixture["eventSource"];let policy:NativeFrameRootPolicyV1=serde_json::from_value(fixture["policy"].clone()).unwrap();
 EVENT_CLOCK.store(law["constructionClock"].as_u64().unwrap(),std::sync::atomic::Ordering::SeqCst);
 let(mut issuer,birth,release)=observe(||NativeFrameEventIssuer::new(event_clock,policy).unwrap());assert_eq!((birth,release),(0,0));assert!(issuer.terminal_is_empty());assert!(!issuer.ready());
 let(mut born,mut freed)=(0,0);let mut identities=[0;2];
 for index in 0..2{
  let now=law[if index==0{"firstEventClock"}else{"secondEventClock"}].as_u64().unwrap();EVENT_CLOCK.store(now,std::sync::atomic::Ordering::SeqCst);let(started,birth,release)=observe(||issuer.observe_event().unwrap());assert!(started);assert_eq!((birth,release),(0,0));assert_eq!(issuer.deadline_us(),Some(now+policy.maximum_elapsed_microseconds));
  for _ in 0..8{if issuer.ready(){break}let(call,birth,release)=observe(||issuer.admit_step().unwrap());assert_eq!((birth,release),(call.receipt_spent.retained_capacity_bytes,call.receipt_spent.released_bytes));born+=birth;freed+=release;}assert!(issuer.ready());
  let mut loan=None;let(call,birth,release)=observe(||issuer.dispatch_step(|cx|{identities[index]=cx.operation().0;loan=cx.original_source_parent()?.admit_loan(cx)?;Ok(())}).unwrap());assert!(call.result.is_ok());assert!(loan.is_some());assert_eq!((birth,release),(call.receipt_spent.retained_capacity_bytes,call.receipt_spent.released_bytes));born+=birth;freed+=release;let stock=issuer.retained_spent();let fuel=issuer.fuel_remaining();let deadline=issuer.deadline_us();assert!(!issuer.observe_event().unwrap());assert_eq!(issuer.retained_spent(),stock);assert_eq!(issuer.fuel_remaining(),fuel);assert_eq!(issuer.deadline_us(),deadline);
  let(done,birth,release)=observe(||issuer.finish_event_step().unwrap());assert!(!done);assert_eq!((birth,release),(0,0));
  let(call,birth,release)=observe(||issuer.dispatch_cleanup_step(|cx|{loan.as_mut().unwrap().close_step(cx.original_source_parent()?,cx)?;Ok(())}).unwrap());assert!(call.result.is_ok());assert!(loan.as_ref().unwrap().terminal_is_empty());assert_eq!((birth,release),(call.receipt_spent.retained_capacity_bytes,call.receipt_spent.released_bytes));born+=birth;freed+=release;drop(loan.take());
  for _ in 0..256{if issuer.terminal_is_empty(){break}let(_,birth,release)=observe(||issuer.finish_event_step().unwrap());born+=birth;freed+=release;}assert!(issuer.terminal_is_empty());assert!(!issuer.ready());
 }
 assert_ne!(identities[0],identities[1]);assert_eq!(born,freed);let(_,birth,release)=observe(||drop(issuer));assert_eq!((birth,release),(0,0));
}
